{
  "qa": [
    {
      "question": "会议中提到的酒店大堂部在新人入职仪式中需要承担哪些具体任务？",
      "answer": "会议明确要求大堂部负责在新人入职仪式上送上蛋糕并由部门领导代表酒店向新人致以祝福。"
    },
    {
      "question": "会议中关于疫情期间的应对措施有哪些具体要求？",
      "answer": "会议要求在活动开场时由主持人前先说明当前疫情期间需规避的相关情况。"
    },
    {
      "question": "会议中提到的酒店营销活动需要哪些部门协同配合？",
      "answer": "会议要求市场部与运营部协同合作，落实大堂部的赠品活动并进行宣传，同时建议财政部门增加资金支持。"
    }
  ]
}
